use world_engine::renderer::ViewRenderer;

const INVENTORY_FL: &str = r#"
intent InventoryWorld {
    schema Product {
        id: Uuid @primary
        name: Text @required
        qty: I64
        price: F64
    }

    action restock(product_id: Uuid, amount: I64) {
        update Product set qty = qty + amount where id == product_id
        return amount
    }

    action add_product(name: Text, qty: I64, price: F64) {
        return qty
    }

    view ProductGrid: Grid {
        source: Product
        interact: [restock, add_product]
    }

    view ProductList: List {
        source: Product
        interact: [restock]
    }

    view ProductForm: Form {
        source: Product
        interact: []
    }
}
"#;

fn make_graph() -> world_engine::IntentGraph {
    world_engine::parse(INVENTORY_FL).expect("파싱 실패")
}

// ─── view_index ─────────────────────────────────────────────

#[test]
fn test_view_index_has_views() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let idx = renderer.view_index();
    let views = idx["views"].as_array().unwrap();
    assert_eq!(views.len(), 3);
}

#[test]
fn test_view_index_fields() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let idx = renderer.view_index();
    let views = idx["views"].as_array().unwrap();
    let first = &views[0];
    assert!(first["intent"].as_str().is_some());
    assert!(first["view"].as_str().is_some());
    assert!(first["type"].as_str().is_some());
    assert!(first["htmlUrl"].as_str().is_some());
    assert!(first["nodesUrl"].as_str().is_some());
}

#[test]
fn test_view_index_count() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let idx = renderer.view_index();
    assert_eq!(idx["count"].as_u64().unwrap(), 3);
}

// ─── render_nodes ───────────────────────────────────────────

#[test]
fn test_render_nodes_returns_some_for_valid_view() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let result = renderer.render_nodes("InventoryWorld", "ProductGrid");
    assert!(result.is_some());
}

#[test]
fn test_render_nodes_returns_none_for_invalid_view() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let result = renderer.render_nodes("InventoryWorld", "NoSuchView");
    assert!(result.is_none());
}

#[test]
fn test_render_nodes_has_required_fields() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    assert_eq!(json["view"].as_str().unwrap(), "ProductGrid");
    assert_eq!(json["intent"].as_str().unwrap(), "InventoryWorld");
    assert!(json["nodes"].as_array().is_some());
    assert!(json["edges"].as_array().is_some());
}

#[test]
fn test_render_nodes_datasource_node_exists() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    let nodes = json["nodes"].as_array().unwrap();
    let ds = nodes.iter().find(|n| n["type"].as_str() == Some("DataSource"));
    assert!(ds.is_some());
    assert_eq!(ds.unwrap()["data"]["intent"].as_str().unwrap(), "InventoryWorld");
}

#[test]
fn test_render_nodes_column_nodes_for_schema_fields() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    let nodes = json["nodes"].as_array().unwrap();
    let cols: Vec<_> = nodes.iter().filter(|n| n["type"].as_str() == Some("Column")).collect();
    // Product 스키마: id, name, qty, price → 4개
    assert_eq!(cols.len(), 4);
}

#[test]
fn test_render_nodes_action_button_nodes() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    let nodes = json["nodes"].as_array().unwrap();
    let acts: Vec<_> = nodes.iter().filter(|n| n["type"].as_str() == Some("ActionButton")).collect();
    // ProductGrid interact: [restock, add_product] → 2개
    assert_eq!(acts.len(), 2);
}

#[test]
fn test_render_nodes_view_container_exists() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    let nodes = json["nodes"].as_array().unwrap();
    let vc = nodes.iter().find(|n| n["type"].as_str() == Some("ViewContainer"));
    assert!(vc.is_some());
    assert_eq!(vc.unwrap()["data"]["viewType"].as_str().unwrap(), "Grid");
}

#[test]
fn test_render_nodes_edges_connect_datasource() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let json = renderer.render_nodes("InventoryWorld", "ProductGrid").unwrap();
    let edges = json["edges"].as_array().unwrap();
    // 4 Column + 2 ActionButton = 6 edges
    assert_eq!(edges.len(), 6);
}

// ─── render_html ────────────────────────────────────────────

#[test]
fn test_render_html_returns_some_for_valid_view() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let result = renderer.render_html("InventoryWorld", "ProductGrid");
    assert!(result.is_some());
}

#[test]
fn test_render_html_returns_none_for_invalid_view() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let result = renderer.render_html("InventoryWorld", "NoSuchView");
    assert!(result.is_none());
}

#[test]
fn test_render_html_is_valid_html_doctype() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.starts_with("<!DOCTYPE html>"));
}

#[test]
fn test_render_html_contains_intent_name() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.contains("InventoryWorld"));
}

#[test]
fn test_render_html_contains_view_name() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.contains("ProductGrid"));
}

#[test]
fn test_render_html_grid_has_table() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.contains("<table"));
}

#[test]
fn test_render_html_list_has_ul() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductList").unwrap();
    assert!(html.contains("<ul"));
}

#[test]
fn test_render_html_form_has_form_view() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductForm").unwrap();
    assert!(html.contains("form-view"));
}

#[test]
fn test_render_html_contains_action_buttons() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.contains("restock"));
    assert!(html.contains("add_product"));
}

#[test]
fn test_render_html_contains_js_fetch() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductGrid").unwrap();
    assert!(html.contains("fetch(SOURCE)"));
}

#[test]
fn test_render_html_no_interact_has_no_action_buttons() {
    let graph = make_graph();
    let renderer = ViewRenderer::new(&graph);
    let html = renderer.render_html("InventoryWorld", "ProductForm").unwrap();
    // ProductForm에는 interact가 없으므로 modal 없음
    assert!(!html.contains("modal-"));
}

