   313→        "<=" => Value::Bool(values_lt(&l, &r) || values_eq(&l, &r)),
   314→        ">"  => Value::Bool(!values_lt(&l, &r) && !values_eq(&l, &r)),
   315→        ">=" => Value::Bool(!values_lt(&l, &r)),
   316→        _    => Value::Null,
   317→    }
   318→}
   319→
   320→fn add_values(l: Value, r: Value) -> Value {
   321→    match (l, r) {
