   323→        (Value::Float(a), Value::Float(b)) => Value::Float(a + b),
   324→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 + b),
   325→        (Value::Float(a), Value::Int(b)) => Value::Float(a + b as f64),
   326→        _ => Value::Null,
   327→    }
   328→}
   329→
   330→fn sub_values(l: Value, r: Value) -> Value {
