   333→        (Value::Float(a), Value::Float(b)) => Value::Float(a - b),
   334→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 - b),
   335→        (Value::Float(a), Value::Int(b)) => Value::Float(a - b as f64),
   336→        _ => Value::Null,
   337→    }
   338→}
   339→
   340→fn mul_values(l: Value, r: Value) -> Value {
   341→    match (l, r) {
   342→        (Value::Int(a), Value::Int(b)) => Value::Int(a * b),
   343→        (Value::Float(a), Value::Float(b)) => Value::Float(a * b),
   344→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 * b),
   345→        (Value::Float(a), Value::Int(b)) => Value::Float(a * b as f64),
   346→        _ => Value::Null,
   347→    }
   348→}
