pub fn start(&self) -> std::io::Result<()> {
    let listener = TcpListener::bind(format!("0.0.0.0:{}", self.port))?;
    println!("World Engine 서버 시작: http://0.0.0.0:{}", self.port);
    println!("라우트 목록: http://0.0.0.0:{}/routes", self.port);
    println!("Lifecycle: http://0.0.0.0:{}/lifecycle", self.port);

    // Lifecycle watcher 백그라운드 시작
    {
        let lc_guard = self.router.lifecycle.lock().unwrap();
        // 각 intent의 lifecycle 출력
        let status = lc_guard.status_json();
        if let Some(intents) = status["intents"].as_array() {
            for i in intents {
                let name = i["intent"].as_str().unwrap_or("?");
                let ltype = i["type"].as_str().unwrap_or("?");
                let ttl = i["ttl_secs"].as_u64();
                match ttl {
                    Some(secs) => println!("  ├─ {} [{}] TTL={}s", name, ltype, secs),
                    None       => println!("  ├─ {} [{}]", name, ltype),
                }
            }
        }
    }

    // lifecycle watcher 스레드 (Arc clone으로 독립 실행)
    let lc_handle = {
        let db = Arc::clone(&self.db);
        let lifecycle = Arc::clone(&self.router.lifecycle);
        std::thread::spawn(move || {
            loop {
                std::thread::sleep(std::time::Duration::from_secs(1));
                if let (Ok(mut lc), Ok(mut db)) = (lifecycle.lock(), db.lock()) {
                    for entry in &lc.entries {
                        if entry.is_expired() {
                            for table in &entry.table_names {
                                db.clear_table(table);
                            }
                        }
                    }
                    // 만료 후 TTL 갱신 (반복 ephemeral 지원)
                    let _ = &mut lc;
                }
            }
        })
    };
    drop(lc_handle); // detach

