use std::time::Duration;
use world_engine::lifecycle::{parse_duration, LifecycleManager};

// ─── parse_duration ──────────────────────────────────────────

#[test]
fn test_parse_seconds() {
    assert_eq!(parse_duration("10s"), Some(Duration::from_secs(10)));
}

#[test]
fn test_parse_minutes() {
    assert_eq!(parse_duration("30m"), Some(Duration::from_secs(1800)));
}

#[test]
fn test_parse_hours() {
    assert_eq!(parse_duration("2h"), Some(Duration::from_secs(7200)));
}

#[test]
fn test_parse_combined_hm() {
    assert_eq!(parse_duration("1h30m"), Some(Duration::from_secs(5400)));
}

#[test]
fn test_parse_combined_hms() {
    assert_eq!(parse_duration("1h30m10s"), Some(Duration::from_secs(5410)));
}

#[test]
fn test_parse_zero() {
    assert_eq!(parse_duration("0s"), Some(Duration::from_secs(0)));
}

#[test]
fn test_parse_invalid_returns_none() {
    assert_eq!(parse_duration("abc"), None);
    assert_eq!(parse_duration(""), None);
    assert_eq!(parse_duration("2x"), None);
}

#[test]
fn test_parse_whitespace_trimmed() {
    assert_eq!(parse_duration("  5s  "), Some(Duration::from_secs(5)));
}

// ─── LifecycleManager ────────────────────────────────────────

const PERSISTENT_FL: &str = r#"
intent StableWorld {
    schema Config {
        id: uuid @primary,
        value: string,
    }
    action set_config(id: uuid, value: string) {
        return value;
    }
}
"#;

const EPHEMERAL_FL: &str = r#"
intent TempWorld {
    context {
        lifecycle: ephemeral(99999s),
        storage: KimDB.memory_buffer,
    }
    schema Session {
        id: uuid @primary,
        token: string,
    }
}
"#;

const SHORT_EPHEMERAL_FL: &str = r#"
intent QuickWorld {
    context {
        lifecycle: ephemeral(1s),
        storage: KimDB.memory_buffer,
    }
    schema Cache {
        id: uuid @primary,
        data: string,
    }
}
"#;

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

#[test]
fn test_persistent_intent_is_always_alive() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    assert!(lc.is_alive("StableWorld"));
}

#[test]
fn test_persistent_no_remaining_secs() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    // persistent는 remaining_secs가 None
    assert_eq!(lc.remaining_secs("StableWorld"), None);
}

#[test]
fn test_ephemeral_intent_initially_alive() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    assert!(lc.is_alive("TempWorld"));
}

#[test]
fn test_ephemeral_has_remaining_secs() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let rem = lc.remaining_secs("TempWorld");
    assert!(rem.is_some());
    assert!(rem.unwrap() > 0);
}

#[test]
fn test_unknown_intent_is_alive() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    // 등록되지 않은 intent는 기본 alive
    assert!(lc.is_alive("NoSuchIntent"));
}

#[test]
fn test_status_json_structure() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let status = lc.status_json();
    assert!(status["count"].as_u64().is_some());
    assert!(status["intents"].as_array().is_some());
}

