use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use crate::ast::{IntentGraph, Lifecycle};
use crate::synthesizer::kimdb::KimDB;

// ============================================================
// Duration 파싱: "2h", "30m", "10s", "1h30m", "2h15m30s"
// ============================================================

pub fn parse_duration(s: &str) -> Option<Duration> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }

    let mut total_secs: u64 = 0;
    let mut num_buf = String::new();
    let mut matched = false;

    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num_buf.push(ch);
        } else {
            let n: u64 = num_buf.parse().ok()?;
            num_buf.clear();
            match ch {
                'h' => { total_secs += n * 3600; matched = true; }
                'm' => { total_secs += n * 60;   matched = true; }
                's' => { total_secs += n;         matched = true; }
                _ => return None,
            }
        }
    }

    // 단위 없이 숫자만 남아있으면 초로 처리
    if !num_buf.is_empty() {
        total_secs += num_buf.parse::<u64>().ok()?;
        matched = true;
    }

    if matched { Some(Duration::from_secs(total_secs)) } else { None }
}

// ============================================================
// LifecycleEntry - intent 하나의 lifecycle 상태
// ============================================================

pub struct LifecycleEntry {
    pub intent_name: String,
    pub table_names: Vec<String>,
    pub created_at: Instant,
    pub ttl: Option<Duration>,  // None = Persistent
}

impl LifecycleEntry {
    pub fn is_expired(&self) -> bool {
        match self.ttl {
            None => false,
            Some(ttl) => self.created_at.elapsed() >= ttl,
        }
    }

    pub fn remaining(&self) -> Option<Duration> {
        let ttl = self.ttl?;
        let elapsed = self.created_at.elapsed();
        if elapsed >= ttl {
            Some(Duration::ZERO)
        } else {
            Some(ttl - elapsed)
        }
    }

    pub fn lifecycle_type(&self) -> &'static str {
        if self.ttl.is_some() { "ephemeral" } else { "persistent" }
    }
}

// ============================================================
// LifecycleManager
// ============================================================

pub struct LifecycleManager {
    pub entries: Vec<LifecycleEntry>,
}

impl LifecycleManager {
    pub fn from_graph(graph: &IntentGraph) -> Self {
        let entries = graph.intents.iter().map(|intent| {
            let table_names: Vec<String> = intent.schemas.iter()
                .map(|s| s.name.clone())
                .collect();

            let ttl = intent.context.as_ref()
                .and_then(|ctx| ctx.lifecycle.as_ref())
                .and_then(|lc| match lc {
                    Lifecycle::Ephemeral(dur_str) => parse_duration(dur_str),
                    Lifecycle::Persistent => None,
                });

            LifecycleEntry {
                intent_name: intent.name.clone(),
                table_names,
                created_at: Instant::now(),
                ttl,
            }
        }).collect();

        LifecycleManager { entries }
    }

    pub fn is_alive(&self, intent_name: &str) -> bool {
        self.entries.iter()
            .find(|e| e.intent_name == intent_name)
            .map(|e| !e.is_expired())
            .unwrap_or(true)
    }

    pub fn remaining_secs(&self, intent_name: &str) -> Option<u64> {
        self.entries.iter()
            .find(|e| e.intent_name == intent_name)
            .and_then(|e| e.remaining())
            .map(|d| d.as_secs())
    }

    // JSON 상태 스냅샷
    pub fn status_json(&self) -> serde_json::Value {
        let intents: Vec<serde_json::Value> = self.entries.iter().map(|e| {
            let alive = !e.is_expired();
            let remaining = e.remaining().map(|d| d.as_secs());
            let mut obj = serde_json::json!({
                "intent": e.intent_name,
                "type": e.lifecycle_type(),
                "alive": alive,
                "tables": e.table_names,
            });
            if let Some(ttl) = e.ttl {
                obj["ttl_secs"] = serde_json::json!(ttl.as_secs());
            }
            if let Some(rem) = remaining {
                obj["remaining_secs"] = serde_json::json!(rem);
            }
            obj
        }).collect();

        serde_json::json!({
            "count": intents.len(),
            "intents": intents,
        })
    }

    // 백그라운드 감시 스레드 시작
    // 만료된 intent의 테이블 rows를 주기적으로 초기화
    pub fn start_watcher(self, db: Arc<Mutex<KimDB>>) -> std::thread::JoinHandle<()> {
        std::thread::spawn(move || {
            loop {
                std::thread::sleep(Duration::from_secs(1));

                for entry in &self.entries {
                    if entry.is_expired() {
                        if let Ok(mut db) = db.lock() {
                            for table in &entry.table_names {
                                db.clear_table(table);
                            }
                        }
                    }
                }
            }
        })
    }
}

// ============================================================
// 만료 이벤트 로그 (선택적 - 서버 응답용)
// ============================================================

pub struct ExpiryLog {
    events: Mutex<Vec<ExpiryEvent>>,
}

struct ExpiryEvent {
    intent: String,
    expired_at: std::time::SystemTime,
    tables_cleared: Vec<String>,
}

impl ExpiryLog {
    pub fn new() -> Arc<Self> {
        Arc::new(ExpiryLog { events: Mutex::new(Vec::new()) })
    }

    pub fn record(&self, intent: &str, tables: &[String]) {
        if let Ok(mut log) = self.events.lock() {
            log.push(ExpiryEvent {
                intent: intent.to_string(),
                expired_at: std::time::SystemTime::now(),
                tables_cleared: tables.to_vec(),
            });
            // 최근 100개만 보관
            if log.len() > 100 {
                log.drain(0..log.len() - 100);
            }
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        let log = self.events.lock().unwrap();
        let events: Vec<serde_json::Value> = log.iter().rev().map(|e| {
            let ts = e.expired_at
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();
            serde_json::json!({
                "intent": e.intent,
                "expired_at_unix": ts,
                "tables_cleared": e.tables_cleared,
            })
        }).collect();
        serde_json::json!({ "events": events, "count": events.len() })
    }
}

// ============================================================
// 로깅 포함 고급 watcher
// ============================================================

pub struct ManagedLifecycle {
    pub manager: LifecycleManager,
    pub log: Arc<ExpiryLog>,
}

impl ManagedLifecycle {
    pub fn new(graph: &IntentGraph) -> Self {
        ManagedLifecycle {
            manager: LifecycleManager::from_graph(graph),
            log: ExpiryLog::new(),
        }
    }

    pub fn start_watcher(self, db: Arc<Mutex<KimDB>>) -> (Arc<ExpiryLog>, std::thread::JoinHandle<()>) {
        let log = Arc::clone(&self.log);
        let log2 = Arc::clone(&self.log);

        let handle = std::thread::spawn(move || {
            // 만료 추적: intent별 이미 처리했는지 기록
            let mut cleared: HashMap<String, bool> = HashMap::new();

            loop {
                std::thread::sleep(Duration::from_secs(1));

                for entry in &self.manager.entries {
                    if entry.is_expired() {
                        let already = cleared.get(&entry.intent_name).copied().unwrap_or(false);
                        if !already {
                            if let Ok(mut db) = db.lock() {
                                for table in &entry.table_names {
                                    db.clear_table(table);
                                }
                            }
                            log2.record(&entry.intent_name, &entry.table_names);
                            cleared.insert(entry.intent_name.clone(), true);
                        }
                    } else {
                        // 살아있으면 cleared 플래그 초기화 (재-ephemeral 가능성)
                        cleared.remove(&entry.intent_name);
                    }
                }
            }
        });

        (log, handle)
    }

    pub fn status_json(&self) -> serde_json::Value {
        self.manager.status_json()
    }
}

