#[test]
fn test_report_json_summary_fields() {
    let graph = parse(NO_PRIMARY_FL);
    let report = DeficiencyDetector::report_json(&graph);
    assert!(report["summary"]["errors"].as_u64().is_some());
    assert!(report["summary"]["warnings"].as_u64().is_some());
    assert!(report["summary"]["infos"].as_u64().is_some());
