fn test_report_json_not_healthy_when_issues() {
    let graph = parse(NO_PRIMARY_FL);
    let report = DeficiencyDetector::report_json(&graph);
    assert!(!report["healthy"].as_bool().unwrap());
}

#[test]
fn test_report_json_by_intent_grouping() {
    let graph = parse(NO_PRIMARY_FL);
    let report = DeficiencyDetector::report_json(&graph);
    let by_intent = report["by_intent"].as_array().unwrap();
    assert!(!by_intent.is_empty());
    let first = &by_intent[0];
    assert!(first["intent"].as_str().is_some());
    assert!(first["count"].as_u64().is_some());
    assert!(first["items"].as_array().is_some());
}

// ─── router: GET /deficiencies ────────────────────────────────

#[test]
fn test_router_deficiencies_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(PERFECT_FL);
    let result = Synthesizer::synthesize(&graph);
    let router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/deficiencies", "");
    assert_eq!(status, 200);
    assert!(json["healthy"].as_bool().unwrap());
}

#[test]
fn test_router_deficiencies_detects_issues() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(NO_CONTEXT_FL);
    let result = Synthesizer::synthesize(&graph);
    let router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/deficiencies", "");
    assert_eq!(status, 200);
    assert!(!json["healthy"].as_bool().unwrap());
    assert!(json["total"].as_u64().unwrap() > 0);
}

