use world_engine::hotreload::HotReloader;

// ─── 헬퍼: 임시 .fl 파일 생성 ───────────────────────────────

fn write_temp_fl(content: &str) -> tempfile::NamedTempFile {
    let mut f = tempfile::NamedTempFile::new().expect("tempfile 생성 실패");
    write!(f, "{}", content).unwrap();
    f.flush().unwrap();
    f
}

// tempfile crate 없이 수동 구현
fn write_fl_file(path: &str, content: &str) {
    std::fs::write(path, content).expect("파일 쓰기 실패");
}

const FL_V1: &str = r#"
intent ShopV1 {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item {
        id: uuid @primary,
        name: string @required,
    }
    action add(name: string) {
        return name;
    }
    view ItemGrid {
        type: Grid,
        source: Item,
        interact: [add],
    }
}
"#;

const FL_V2: &str = r#"
intent ShopV2 {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

// ─── load_graph ───────────────────────────────────────────────

#[test]
fn test_load_graph_parses_valid_file() {
    let path = "/tmp/we_test_v1.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    let graph = reloader.load_graph();
    assert!(graph.is_ok());
    let g = graph.unwrap();
    assert_eq!(g.intents[0].name, "ShopV1");
}

#[test]
fn test_load_graph_returns_error_for_invalid_fl() {
    let path = "/tmp/we_test_invalid.fl";
    write_fl_file(path, "this is not valid FL syntax @@@@");
    let reloader = HotReloader::new(path);
    let result = reloader.load_graph();
    assert!(result.is_err());
}

#[test]
fn test_load_graph_error_for_missing_file() {
    let reloader = HotReloader::new("/tmp/we_nonexistent_12345.fl");
    let result = reloader.load_graph();
    assert!(result.is_err());
}

// ─── force_reload ─────────────────────────────────────────────

#[test]
fn test_force_reload_increments_count() {
    let path = "/tmp/we_test_reload_count.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    assert_eq!(reloader.reload_count(), 0);
    reloader.force_reload().unwrap();
    assert_eq!(reloader.reload_count(), 1);
    reloader.force_reload().unwrap();
    assert_eq!(reloader.reload_count(), 2);
}

#[test]
fn test_force_reload_records_error() {
    let path = "/tmp/we_test_reload_err.fl";
    write_fl_file(path, "invalid @@");
    let reloader = HotReloader::new(path);
    let result = reloader.force_reload();
    assert!(result.is_err());
    assert!(reloader.last_error().is_some());
}

#[test]
fn test_force_reload_clears_error_on_success() {
    let path = "/tmp/we_test_reload_clear.fl";
    // 처음에는 잘못된 내용
    write_fl_file(path, "invalid @@");
    let reloader = HotReloader::new(path);
    let _ = reloader.force_reload();
    assert!(reloader.last_error().is_some());

    // 올바른 내용으로 교체 후 reload
    write_fl_file(path, FL_V1);
    reloader.force_reload().unwrap();
    assert!(reloader.last_error().is_none());
}

// ─── check_changed ────────────────────────────────────────────

#[test]
fn test_check_changed_false_immediately_after_creation() {
    let path = "/tmp/we_test_no_change.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    // 생성 직후 mtime 동일 → false
    assert!(!reloader.check_changed());
}

#[test]
fn test_check_changed_true_after_file_write() {
    let path = "/tmp/we_test_changed.fl";
    write_fl_file(path, FL_V1);

    // 약간 대기 (mtime 해상도)
    std::thread::sleep(std::time::Duration::from_millis(10));

    let reloader = HotReloader::new(path);
    // 첫 check → 초기화
    reloader.check_changed();

    // 파일 재작성 (mtime 변경)
    std::thread::sleep(std::time::Duration::from_millis(100));
    write_fl_file(path, FL_V2);
    std::thread::sleep(std::time::Duration::from_millis(100));

    assert!(reloader.check_changed());
}

// ─── check_and_reload ─────────────────────────────────────────

#[test]
fn test_check_and_reload_none_when_unchanged() {
    let path = "/tmp/we_test_no_reload.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    // check_changed()를 먼저 소비
    reloader.check_changed();
    let result = reloader.check_and_reload();
    assert!(result.is_none());
}

#[test]
fn test_check_and_reload_some_when_changed() {
    let path = "/tmp/we_test_do_reload.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    reloader.check_changed(); // 초기화

    std::thread::sleep(std::time::Duration::from_millis(100));
    write_fl_file(path, FL_V2);
    std::thread::sleep(std::time::Duration::from_millis(100));

    let result = reloader.check_and_reload();
    assert!(result.is_some());
    let graph = result.unwrap().unwrap();
    assert_eq!(graph.intents[0].name, "ShopV2");
}

// ─── file_exists ─────────────────────────────────────────────

#[test]
fn test_file_exists_true_for_existing() {
    let path = "/tmp/we_test_exists.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    assert!(reloader.file_exists());
}

#[test]
fn test_file_exists_false_for_missing() {
    let reloader = HotReloader::new("/tmp/we_no_such_file_xyz.fl");
    assert!(!reloader.file_exists());
}

// ─── status_json ──────────────────────────────────────────────

#[test]
fn test_status_json_structure() {
    let path = "/tmp/we_test_status.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    let status = reloader.status_json();
    assert!(status["path"].as_str().is_some());
    assert!(status["exists"].as_bool().is_some());
    assert!(status["reload_count"].as_u64().is_some());
}

#[test]
fn test_status_json_path_correct() {
    let path = "/tmp/we_test_path.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    let status = reloader.status_json();
    assert!(status["path"].as_str().unwrap().contains("we_test_path.fl"));
}

#[test]
fn test_status_json_reload_count_after_reload() {
    let path = "/tmp/we_test_count_json.fl";
    write_fl_file(path, FL_V1);
    let reloader = HotReloader::new(path);
    reloader.force_reload().unwrap();
    let status = reloader.status_json();
    assert_eq!(status["reload_count"].as_u64().unwrap(), 1);
}

// ─── router: GET /reload/status ──────────────────────────────

#[test]
fn test_router_reload_status_without_reloader() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer, parse};
    let graph = parse(FL_V1).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/reload/status", "");
    assert_eq!(status, 200);
    assert_eq!(json["enabled"].as_bool(), Some(false));
}

#[test]
fn test_router_reload_status_with_reloader() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer, parse};
    let path = "/tmp/we_test_router_reload.fl";
    write_fl_file(path, FL_V1);
    let graph = parse(FL_V1).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let reloader = Arc::new(HotReloader::new(path));
    let router = Router::from_graph(graph).with_reloader(Arc::clone(&reloader));
    let (status, json) = router.handle(&mut { result.db }, "GET", "/reload/status", "");
    assert_eq!(status, 200);
    assert!(json["path"].as_str().is_some());
}

#[test]
fn test_router_post_reload_without_reloader() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer, parse};
    let graph = parse(FL_V1).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "POST", "/reload", "");
    assert_eq!(status, 400);
    assert!(json["error"].as_str().is_some());
}

#[test]
fn test_router_post_reload_with_reloader() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer, parse};
    let path = "/tmp/we_test_post_reload.fl";
    write_fl_file(path, FL_V1);
    let graph = parse(FL_V1).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let reloader = Arc::new(HotReloader::new(path));
    let router = Router::from_graph(graph).with_reloader(Arc::clone(&reloader));
    let (status, json) = router.handle(&mut { result.db }, "POST", "/reload", "");
    assert_eq!(status, 200);
    assert!(json["ok"].as_bool().unwrap());
    assert!(json["intents"].as_array().is_some());
}

