                                    "action": route.action,
                                    "result": codec::value_to_json(&result),
                                })),
                                Err(e) => (500, serde_json::json!({
                                    "error": e.to_string()
                                })),
                            }
                        }
                    }
                }
            }
        }
    }
}

use crate::ast::{IntentGraph, IntentNode, FnDef, StructDef};

// ============================================================
// 충돌 종류
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum ConflictKind {
    DuplicateIntent(String),
    DuplicateSchema { intent: String, schema: String },
    DuplicateFunction(String),
    DuplicateStruct(String),
}

impl std::fmt::Display for ConflictKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConflictKind::DuplicateIntent(n)             => write!(f, "duplicate_intent:{}", n),
            ConflictKind::DuplicateSchema { intent, schema } =>
                write!(f, "duplicate_schema:{}.{}", intent, schema),
            ConflictKind::DuplicateFunction(n)           => write!(f, "duplicate_fn:{}", n),
            ConflictKind::DuplicateStruct(n)             => write!(f, "duplicate_struct:{}", n),
        }
    }
}

// ============================================================
// 충돌 항목
// ============================================================

#[derive(Debug, Clone)]
pub struct FederationConflict {
    pub kind: ConflictKind,
    pub source_a: String,
    pub source_b: String,
    pub message: String,
}

impl FederationConflict {
    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "kind": self.kind.to_string(),
            "source_a": self.source_a,
            "source_b": self.source_b,
            "message": self.message,
        })
    }
}

// ============================================================
// 소스 파일 항목
// ============================================================

#[derive(Debug, Clone)]
pub struct FederationSource {
    pub path: String,
    pub intent_names: Vec<String>,
    pub schema_count: usize,
    pub action_count: usize,
    pub function_count: usize,
}

impl FederationSource {
    fn from_graph(path: &str, graph: &IntentGraph) -> Self {
        let intent_names = graph.intents.iter().map(|i| i.name.clone()).collect();
        let schema_count = graph.intents.iter().map(|i| i.schemas.len()).sum();
        let action_count = graph.intents.iter().map(|i| i.actions.len()).sum();
        FederationSource {
            path: path.to_string(),
            intent_names,
            schema_count,
            action_count,
            function_count: graph.functions.len(),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "path": self.path,
            "intents": self.intent_names,
            "schema_count": self.schema_count,
            "action_count": self.action_count,
            "function_count": self.function_count,
        })
    }
}

// ============================================================
// 합성 결과
// ============================================================

pub struct FederationResult {
    pub merged: IntentGraph,
    pub sources: Vec<FederationSource>,
    pub conflicts: Vec<FederationConflict>,
}

impl FederationResult {
    pub fn is_clean(&self) -> bool {
        self.conflicts.is_empty()
    }

    pub fn to_json(&self) -> serde_json::Value {
        let sources: Vec<_> = self.sources.iter().map(|s| s.to_json()).collect();
        let conflicts: Vec<_> = self.conflicts.iter().map(|c| c.to_json()).collect();

        let total_intents = self.merged.intents.len();
        let total_schemas: usize = self.merged.intents.iter().map(|i| i.schemas.len()).sum();
        let total_actions: usize = self.merged.intents.iter().map(|i| i.actions.len()).sum();

        serde_json::json!({
            "clean": self.is_clean(),
            "conflict_count": self.conflicts.len(),
            "merged": {
                "intent_count": total_intents,
                "schema_count": total_schemas,
                "action_count": total_actions,
                "function_count": self.merged.functions.len(),
                "intents": self.merged.intents.iter().map(|i| &i.name).collect::<Vec<_>>(),
            },
            "sources": sources,
            "conflicts": conflicts,
        })
    }
}

// ============================================================
// FederationMerger - 여러 IntentGraph 합성기
// ============================================================

pub struct FederationMerger {
    graphs: Vec<(String, IntentGraph)>,  // (path, graph)
}

impl FederationMerger {
    pub fn new() -> Self {
        FederationMerger { graphs: Vec::new() }
    }

    // 파일 경로 → 읽기 + 파싱 + 추가
    pub fn add_file(&mut self, path: &str) -> Result<(), String> {
        let src = std::fs::read_to_string(path)
            .map_err(|e| format!("파일 읽기 실패 '{}': {}", path, e))?;
        let graph = crate::parse(&src)
            .map_err(|e| format!("파싱 오류 '{}': {}", path, e.message))?;
        self.graphs.push((path.to_string(), graph));
        Ok(())
    }

    // 직접 그래프 추가 (테스트용)
    pub fn add_graph(&mut self, label: &str, graph: IntentGraph) {
        self.graphs.push((label.to_string(), graph));
    }

    pub fn source_count(&self) -> usize {
        self.graphs.len()
    }

    // 합성 실행
    pub fn merge(&self) -> FederationResult {
        let mut merged = IntentGraph::new();
        let mut conflicts = Vec::new();
        let mut sources = Vec::new();

        // 등록된 intent 이름 → 최초 소스 경로
        let mut seen_intents: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();
        let mut seen_fns: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();
        let mut seen_structs: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();

        for (path, graph) in &self.graphs {
            sources.push(FederationSource::from_graph(path, graph));

            // ─── intent 병합 ────────────────────────────────────
            for intent in &graph.intents {
                if let Some(prev_path) = seen_intents.get(&intent.name) {
                    conflicts.push(FederationConflict {
                        kind: ConflictKind::DuplicateIntent(intent.name.clone()),
                        source_a: prev_path.clone(),
                        source_b: path.clone(),
                        message: format!(
                            "intent '{}' 가 '{}' 와 '{}' 에 중복 정의되어 있습니다",
                            intent.name, prev_path, path
                        ),
                    });
                    // 충돌이지만 첫 번째 것 유지 (skip)
                    continue;
                }

                // schema 중복 체크 (다른 intent와 같은 스키마명)
                for schema in &intent.schemas {
                    let key = format!("{}.{}", intent.name, schema.name);
                    // 같은 intent 내 중복은 validator가 처리하므로 여기선 cross-intent 체크
                    let _ = key; // 현재는 intent 격리이므로 cross-intent schema 중복은 허용
                }

                seen_intents.insert(intent.name.clone(), path.clone());
                merged.intents.push(intent.clone());
            }

            // ─── function 병합 ───────────────────────────────────
            for func in &graph.functions {
                if let Some(prev_path) = seen_fns.get(&func.name) {
                    conflicts.push(FederationConflict {
                        kind: ConflictKind::DuplicateFunction(func.name.clone()),
                        source_a: prev_path.clone(),
                        source_b: path.clone(),
                        message: format!(
                            "함수 '{}' 가 '{}' 와 '{}' 에 중복 정의되어 있습니다",
                            func.name, prev_path, path
                        ),
                    });
                    continue;
                }
                seen_fns.insert(func.name.clone(), path.clone());
                merged.functions.push(func.clone());
            }

            // ─── struct 병합 ─────────────────────────────────────
            for st in &graph.structs {
                if let Some(prev_path) = seen_structs.get(&st.name) {
                    conflicts.push(FederationConflict {
                        kind: ConflictKind::DuplicateStruct(st.name.clone()),
                        source_a: prev_path.clone(),
                        source_b: path.clone(),
                        message: format!(
                            "struct '{}' 가 '{}' 와 '{}' 에 중복 정의되어 있습니다",
                            st.name, prev_path, path
                        ),
                    });
                    continue;
                }
                seen_structs.insert(st.name.clone(), path.clone());
                merged.structs.push(st.clone());
            }
        }

        FederationResult { merged, sources, conflicts }
    }

    // 상태 JSON (merge 실행 없이 소스만 조회)
    pub fn status_json(&self) -> serde_json::Value {
        let sources: Vec<serde_json::Value> = self.graphs.iter().map(|(path, graph)| {
            FederationSource::from_graph(path, graph).to_json()
        }).collect();

        serde_json::json!({
            "source_count": self.graphs.len(),
            "sources": sources,
        })
    }
}

impl Default for FederationMerger {
    fn default() -> Self { Self::new() }
}

// ============================================================
// 유틸: 여러 파일 → 합성 그래프 (편의 함수)
// ============================================================

pub fn merge_files(paths: &[&str]) -> Result<FederationResult, Vec<String>> {
    let mut merger = FederationMerger::new();
    let mut errors = Vec::new();

    for path in paths {
        if let Err(e) = merger.add_file(path) {
            errors.push(e);
        }
    }

    if !errors.is_empty() {
        return Err(errors);
    }

    Ok(merger.merge())
}

