    // JSON body → MutationOp 파싱
    pub fn from_json(json: &serde_json::Value) -> Result<Self, String> {
        let op = json["op"].as_str().ok_or("'op' 필드 없음")?;

        match op {
            "add_field" => {
                let intent = str_field(json, "intent")?;
                let schema = str_field(json, "schema")?;
                let field_name = str_field(json, "field_name")?;
                let ft_str = str_field(json, "field_type")?;
                let field_type = parse_fl_type(&ft_str)?;
                let required = json["required"].as_bool().unwrap_or(false);
                Ok(MutationOp::AddField { intent, schema, field_name, field_type, required })
            }
            "remove_field" => {
                let intent = str_field(json, "intent")?;
                let schema = str_field(json, "schema")?;
                let field_name = str_field(json, "field_name")?;
                Ok(MutationOp::RemoveField { intent, schema, field_name })
            }
            "add_view" => {
                let intent = str_field(json, "intent")?;
                let view_name = str_field(json, "view_name")?;
                let vt_str = str_field(json, "view_type")?;
                let view_type = parse_view_type(&vt_str);
                let source = str_field(json, "source")?;
                Ok(MutationOp::AddView { intent, view_name, view_type, source })
            }
            "remove_view" => {
                let intent = str_field(json, "intent")?;
                let view_name = str_field(json, "view_name")?;
                Ok(MutationOp::RemoveView { intent, view_name })
            }
            "set_lifecycle" => {
                let intent = str_field(json, "intent")?;
                let lc_str = str_field(json, "lifecycle")?;
                let lifecycle = parse_lifecycle(&lc_str)?;
                Ok(MutationOp::SetLifecycle { intent, lifecycle })
            }
            other => Err(format!("알 수 없는 op: '{}'", other)),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        match self {
            MutationOp::AddField { intent, schema, field_name, field_type, required } =>
                serde_json::json!({
                    "op": "add_field",
                    "intent": intent, "schema": schema,
                    "field_name": field_name,
                    "field_type": field_type.to_string(),
                    "required": required,
                }),
            MutationOp::RemoveField { intent, schema, field_name } =>
                serde_json::json!({
                    "op": "remove_field",
                    "intent": intent, "schema": schema,
                    "field_name": field_name,
                }),
            MutationOp::AddView { intent, view_name, view_type, source } => {
                let vt = match view_type {
                    ViewType::Grid => "Grid", ViewType::List => "List",
                    ViewType::Form => "Form", ViewType::Custom(s) => s.as_str(),
                };
                serde_json::json!({
                    "op": "add_view",
                    "intent": intent, "view_name": view_name,
                    "view_type": vt, "source": source,
                })
            }
            MutationOp::RemoveView { intent, view_name } =>
                serde_json::json!({
                    "op": "remove_view",
                    "intent": intent, "view_name": view_name,
                }),
            MutationOp::SetLifecycle { intent, lifecycle } => {
                let lc = match lifecycle {
                    Lifecycle::Persistent => "persistent".to_string(),
                    Lifecycle::Ephemeral(s) => format!("ephemeral({})", s),
                };
                serde_json::json!({ "op": "set_lifecycle", "intent": intent, "lifecycle": lc })
            }
        }
    }
}

// ============================================================
// Mutation 이력 항목
// ============================================================

pub struct MutationRecord {
    pub op: MutationOp,
    pub success: bool,
    pub message: String,
    pub applied_at: SystemTime,
}

impl MutationRecord {
    pub fn to_json(&self) -> serde_json::Value {
        let ts = self.applied_at
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        serde_json::json!({
            "op": self.op.to_json(),
            "success": self.success,
            "message": self.message,
            "applied_at_unix": ts,
        })
    }
}

// ============================================================
// MutationEngine
// ============================================================

pub struct MutationEngine {
    log: Mutex<Vec<MutationRecord>>,
}

impl MutationEngine {
    pub fn new() -> Self {
        MutationEngine { log: Mutex::new(Vec::new()) }
    }

    // IntentGraph에 mutation 직접 적용
    pub fn apply(&self, graph: &mut IntentGraph, op: MutationOp) -> (bool, String) {
        let result = Self::execute(graph, &op);
        let (success, msg) = match &result {
            Ok(m)  => (true, m.clone()),
            Err(e) => (false, e.clone()),
        };
        if let Ok(mut log) = self.log.lock() {
            log.push(MutationRecord {
                op,
                success,
                message: msg.clone(),
                applied_at: SystemTime::now(),
            });
            if log.len() > 200 {
                let excess = log.len() - 200;
                log.drain(0..excess);
            }
        }
        (success, msg)
    }

    fn execute(graph: &mut IntentGraph, op: &MutationOp) -> Result<String, String> {
        match op {
            MutationOp::AddField { intent, schema, field_name, field_type, required } => {
                let intent_node = graph.intents.iter_mut()
                    .find(|i| &i.name == intent)
                    .ok_or_else(|| format!("intent '{}' 없음", intent))?;
                let schema_node = intent_node.schemas.iter_mut()
                    .find(|s| &s.name == schema)
                    .ok_or_else(|| format!("schema '{}' 없음", schema))?;

                // 중복 필드 체크
                if schema_node.fields.iter().any(|f| &f.name == field_name) {
                    return Err(format!("필드 '{}.{}' 이미 존재", schema, field_name));
                }

                let mut annotations = Vec::new();
                if *required { annotations.push(Annotation::Required); }

                schema_node.fields.push(SchemaField {
                    name: field_name.clone(),
                    field_type: field_type.clone(),
                    annotations,
                });
                Ok(format!("필드 '{}.{}' 추가 완료", schema, field_name))
            }

            MutationOp::RemoveField { intent, schema, field_name } => {
                let intent_node = graph.intents.iter_mut()
                    .find(|i| &i.name == intent)
                    .ok_or_else(|| format!("intent '{}' 없음", intent))?;
                let schema_node = intent_node.schemas.iter_mut()
                    .find(|s| &s.name == schema)
                    .ok_or_else(|| format!("schema '{}' 없음", schema))?;

                let before = schema_node.fields.len();
                schema_node.fields.retain(|f| &f.name != field_name);
                if schema_node.fields.len() == before {
                    return Err(format!("필드 '{}.{}' 없음", schema, field_name));
                }
                Ok(format!("필드 '{}.{}' 제거 완료", schema, field_name))
            }

            MutationOp::AddView { intent, view_name, view_type, source } => {
                let intent_node = graph.intents.iter_mut()
                    .find(|i| &i.name == intent)
                    .ok_or_else(|| format!("intent '{}' 없음", intent))?;

                // 중복 view 체크
                if intent_node.views.iter().any(|v| &v.name == view_name) {
                    return Err(format!("view '{}' 이미 존재", view_name));
                }
                // source 스키마 존재 체크
                if !intent_node.schemas.iter().any(|s| &s.name == source) {
                    return Err(format!("source 스키마 '{}' 없음", source));
                }

                intent_node.views.push(View {
                    name: view_name.clone(),
                    view_type: view_type.clone(),
                    source: source.clone(),
                    interactions: Vec::new(),
                });
                Ok(format!("view '{}' 추가 완료", view_name))
            }

            MutationOp::RemoveView { intent, view_name } => {
                let intent_node = graph.intents.iter_mut()
                    .find(|i| &i.name == intent)
                    .ok_or_else(|| format!("intent '{}' 없음", intent))?;

                let before = intent_node.views.len();
                intent_node.views.retain(|v| &v.name != view_name);
                if intent_node.views.len() == before {
                    return Err(format!("view '{}' 없음", view_name));
                }
                Ok(format!("view '{}' 제거 완료", view_name))
            }

            MutationOp::SetLifecycle { intent, lifecycle } => {
                let intent_node = graph.intents.iter_mut()
                    .find(|i| &i.name == intent)
                    .ok_or_else(|| format!("intent '{}' 없음", intent))?;

                match intent_node.context.as_mut() {
                    Some(ctx) => { ctx.lifecycle = Some(lifecycle.clone()); }
                    None => {
                        intent_node.context = Some(ContextBlock {
                            lifecycle: Some(lifecycle.clone()),
                            storage: None,
                        });
                    }
                }
                Ok(format!("intent '{}' lifecycle 변경 완료", intent))
            }
        }
    }

    pub fn log_len(&self) -> usize {
        self.log.lock().map(|l| l.len()).unwrap_or(0)
    }

    pub fn log_json(&self) -> serde_json::Value {
        let log = self.log.lock().unwrap();
        let records: Vec<_> = log.iter().rev().map(|r| r.to_json()).collect();
        serde_json::json!({
            "total": records.len(),
            "records": records,
        })
    }
}

impl Default for MutationEngine {
    fn default() -> Self { Self::new() }
}

// ============================================================
// 파싱 유틸
// ============================================================

fn str_field(json: &serde_json::Value, key: &str) -> Result<String, String> {
    json[key].as_str()
        .map(|s| s.to_string())
        .ok_or_else(|| format!("'{}' 필드 없음 또는 문자열 아님", key))
}

fn parse_fl_type(s: &str) -> Result<FlType, String> {
    match s.trim().to_lowercase().as_str() {
        "i64" | "int" | "integer" => Ok(FlType::I64),
        "f64" | "float" | "double" => Ok(FlType::F64),
        "string" | "text" | "str" => Ok(FlType::String),
        "bool" | "boolean" => Ok(FlType::Bool),
        "uuid" => Ok(FlType::Uuid),
        other => Ok(FlType::Custom(other.to_string())),
    }
}

fn parse_view_type(s: &str) -> ViewType {
    match s.trim() {
        "Grid" | "grid" => ViewType::Grid,
        "List" | "list" => ViewType::List,
        "Form" | "form" => ViewType::Form,
        other => ViewType::Custom(other.to_string()),
    }
}

fn parse_lifecycle(s: &str) -> Result<Lifecycle, String> {
    let s = s.trim();
    if s == "persistent" {
        return Ok(Lifecycle::Persistent);
    }
    if let Some(inner) = s.strip_prefix("ephemeral(").and_then(|s| s.strip_suffix(')')) {
        // duration 유효성 확인
        crate::lifecycle::parse_duration(inner)
            .ok_or_else(|| format!("잘못된 duration: '{}'", inner))?;
        return Ok(Lifecycle::Ephemeral(inner.to_string()));
    }
    Err(format!("잘못된 lifecycle: '{}' (예: persistent, ephemeral(2h))", s))
}

